import { MeshPhysicalNodeMaterial } from 'three/webgpu';
import {
  texture,
  uv,
  mix,
  smoothstep,
  color,
  vec2,
  vec3,
  float,
  fract,
  sin,
  dot,
} from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, PlaneGeometry, DirectionalLight, Color } = THREE;

  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const root = new Group();
  root.name = 'hero-headline';

  const disposables = [];
  const timelines = [];

  // ---- engineered gradient panel (image + gradient + subtle grain) ----
  const panelW = 4.4;
  const panelH = 2.75;
  const panelGeo = new PlaneGeometry(panelW, panelH, 1, 1);
  disposables.push(panelGeo);

  const uvNode = uv();
  const gradient = mix(
    color(colors.surface),
    color(colors.ink),
    smoothstep(float(0.0), float(1.0), uvNode.y)
  );

  const grainSeed = dot(uvNode.mul(4321.123), vec2(12.9898, 78.233));
  const grainRaw = fract(sin(grainSeed).mul(43758.5453));
  const grainSigned = grainRaw.sub(0.5).mul(0.05);
  const grainVec = vec3(grainSigned, grainSigned, grainSigned);

  const panelMat = new MeshPhysicalNodeMaterial({
    color: new Color(colors.ink),
  });
  panelMat.roughness = 0.55;
  panelMat.metalness = 0.4;
  panelMat.clearcoat = 0.2;
  panelMat.clearcoatRoughness = 0.35;
  panelMat.colorNode = gradient.add(grainVec);
  disposables.push(panelMat);

  const panel = new (THREE.Mesh)(panelGeo, panelMat);
  panel.position.set(0, 0, 0);
  root.add(panel);

  if (config.imageUrl) {
    ctx.textureLoader
      .loadTexture(config.imageUrl)
      .then((tex) => {
        disposables.push(tex);
        const texColor = texture(tex);
        const composited = mix(gradient, texColor, float(0.55)).add(grainVec);
        panelMat.colorNode = composited;
        panelMat.needsUpdate = true;
      })
      .catch(() => {
        // keep pure gradient panel on load failure
      });
  }

  // ---- rim / accent light, node-local only ----
  const rimLight = new DirectionalLight(new Color(colors.accent), 0.7);
  rimLight.position.set(-2.2, 1.6, 2.0);
  root.add(rimLight);

  // ---- accent underline strip (the one brightest element) ----
  const accentGeo = new PlaneGeometry(1.1, 0.03, 1, 1);
  disposables.push(accentGeo);
  const accentMat = new MeshPhysicalNodeMaterial({
    color: new Color(colors.accent),
  });
  accentMat.roughness = 0.4;
  accentMat.metalness = 0.2;
  accentMat.emissive = new Color(colors.accent);
  accentMat.emissiveIntensity = 1.4;
  disposables.push(accentMat);
  const accentStrip = new (THREE.Mesh)(accentGeo, accentMat);
  accentStrip.position.set(0, -0.62, 0.02);
  root.add(accentStrip);

  // ---- text content (verbatim, ASCII-safe body copy) ----
  const items =
    config.textContent ?? config.intent?.visualSpec?.textContent ?? [];

  const textObjects = [];
  let yCursor = 0.2;
  for (const item of items) {
    const fontSize = item.typography?.fontSize ?? 31;
    const textObj = ctx.fontAtlas.createText(item.text ?? '', {
      fontSize,
      color: colors.paper,
      align: 'center',
      maxWidthPx: 900,
      letterSpacingPx: 0.4,
    });
    textObj.position.set(0, yCursor, 0.04);
    root.add(textObj);
    textObjects.push(textObj);
    yCursor -= 0.5;
  }

  // ---- weighted, non-perpetual entrance (static composition otherwise) ----
  root.position.y += 0.3;
  root.traverse((child) => {
    if (child.material) child.material.transparent = false;
  });

  const tl = gsap.timeline();
  tl.to(root.position, {
    y: root.position.y - 0.3,
    duration: 0.8,
    ease: 'power3.out',
  });
  tl.fromTo(
    root.scale,
    { x: 0.98, y: 0.98, z: 0.98 },
    { x: 1.0, y: 1.0, z: 1.0, duration: 0.9, ease: 'power4.out' },
    0
  );
  timelines.push(tl);

  // ---- cinematic primitives (none configured, but honor the contract) ----
  const primitiveHandles = [];
  const primitives = config.cinematicPrimitives ?? [];
  for (const prim of primitives) {
    const fn = ctx.primitives?.[prim.name];
    if (typeof fn === 'function') {
      const handle = fn(root, prim.params ?? {});
      if (handle) primitiveHandles.push(handle);
    }
  }

  root.userData.handlers = {};

  root.userData.cleanup = () => {
    for (const tlx of timelines) tlx.kill();
    for (const handle of primitiveHandles) {
      handle?.cleanup?.();
    }
    for (const textObj of textObjects) {
      root.remove(textObj);
      textObj.traverse?.((c) => {
        c.geometry?.dispose?.();
        c.material?.dispose?.();
      });
    }
    for (const res of disposables) {
      res?.dispose?.();
    }
    root.remove(panel);
    root.remove(accentStrip);
    root.remove(rimLight);
  };

  return root;
}
